def execute(name, prompt, workspace, *, cancel=None, process_callback=None, memory_packet=None, execution_constraints=None):
    start = time.monotonic()
    if cancel and cancel.is_set():
        raise RuntimeError("Tarefa cancelada.")
    from . import canonical_memory
    from .policy import validate_prompt
    from . import request_controls as controls
    constraints=controls.normalize(execution_constraints)
    packet = memory_packet if memory_packet is not None else canonical_memory.prepare(prompt,mode=canonical_memory.mode_for_provider(name,constraints),max_chars=canonical_memory.packet_char_cap(constraints,SYSTEM),prompt_limit=controls.prompt_limit(constraints))
    if canonical_memory.digest(packet['prompt'].encode()) != packet['receipt']['packet_sha256']:
        raise ValueError("Pacote de memória alterado; envio bloqueado.")
    if constraints and name != constraints['required_provider']:
        raise ValueError('Executor diverge da restrição; chamada bloqueada.')
    controls.enforce_packet(packet,constraints,SYSTEM)
    if constraints: controls.quote(constraints)
    prompt = packet['prompt'] if name in ('mimo','kimi','deepseek') else validate_prompt(packet['prompt'],controls.packet_limit(constraints))

receipt = {'generation': manifest['generation'], 'built_at': manifest['built_at'],
    'freshness': freshness, 'sources': references, 'packet_sha256': digest(body.encode()),
    'context_bytes': len(body.encode()), 'coverage': 'PARTIAL_RETRIEVAL_NOT_FULL_CORPUS',
    'blocked_passages': blocked, 'weights_modified': False, 'memory_mode':mode, 'packing':'CONSERVATIVE_UTF8_BYTES' if maximum else 'BOUNDED_RETRIEVAL'}
return {'prompt': body, 'receipt': receipt}

def create(self,prompt,request_id,execution_constraints=None):
    c=controls.normalize(execution_constraints); serialized=controls.encode(c)
    prompt=validate_prompt(prompt,controls.prompt_limit(c))
    if not isinstance(request_id,str):raise ValueError('Identificador inválido.')
    uuid.UUID(request_id)
    if not self.runtime.source_status()['ok']:raise ValueError('Fontes não conferem.')
    with self.runtime.db() as db:
        existing=db.execute('SELECT id,prompt,execution_constraints FROM coordination_jobs WHERE request_id=?',(request_id,)).fetchone()
    if existing:
        if existing['prompt'] != prompt or (existing['execution_constraints'] or 'null') != serialized:
            raise ValueError('Identificador já usado com outro pedido/restrições.')
        return self.get(existing['id'])
    if c:
        preview=self.runtime.preview(prompt,c)
        if not preview['selected']: raise ValueError('Executor obrigatório inelegível; nenhum Work criado.')
    retired=BASE/'state/session_requests'/f'{request_id}.json'
    if retired.is_file() and json.loads(retired.read_bytes()).get('status')=='superseded_before_submission':
        raise ValueError('Pedido retirado; não submeter.')
    with self.runtime.db() as db:
        db.execute('BEGIN IMMEDIATE')
        existing=db.execute('SELECT id,prompt,execution_constraints FROM coordination_jobs WHERE request_id=?',(request_id,)).fetchone()
        if existing:
            if existing['prompt']!=prompt or (existing['execution_constraints'] or 'null')!=serialized:raise ValueError('Identificador já usado por outro pedido.')
            job_id=existing['id']
        else:
            pending=db.execute("SELECT count(*) FROM coordination_jobs WHERE stage NOT IN ('completed','failed','cancelled')").fetchone()[0]
            if pending>=5:raise ValueError('Há cinco coordenações pendentes. Conclua ou cancele uma.')
            job_id=str(uuid.uuid4());stamp=now()
            db.execute('INSERT INTO coordination_jobs(id,request_id,prompt,created_at,updated_at,stage,execution_constraints) VALUES(?,?,?,?,?,?,?)',
                (job_id,request_id,prompt,stamp,stamp,'awaiting_dispatch',serialized))

def _change(self,job_id,expected,new_stage,action,**fields):
    if not set(fields)<={'thread_id','prepared_prompt','execution_task_id','final_text','error','draft_source','synthesis_source','assistance_reason'}:
        raise ValueError('Campos de transição inválidos.')
    with self.runtime.db() as db:
        db.execute('BEGIN IMMEDIATE')
        row=db.execute('SELECT stage,execution_constraints FROM coordination_jobs WHERE id=?',(job_id,)).fetchone()
        if row is None or row['stage'] not in expected:
            raise ValueError('Etapa incompatível ou já realizada; leia o estado antes de agir.')
        if action in ('begin_draft','begin_synthesis'):
            controls.check_work(db,json.loads(row['execution_constraints']) if row['execution_constraints'] else None)
        previous=row['stage'];fields.update(stage=new_stage,updated_at=now())
        db.execute('UPDATE coordination_jobs SET '+','.join(k+'=?' for k in fields)+',version=version+1 WHERE id=?',(*fields.values(),job_id))
        db.execute('INSERT INTO coordination_events(job_id,at,action,from_stage,to_stage) VALUES(?,?,?,?,?)',(job_id,now(),action,previous,new_stage))
    return self.get(job_id)

    return self._change(job_id,{'synthesis_ready','synthesis_waiting'},'completed',action,
        final_text=answer.strip(),synthesis_source='iald_coordinator' if payload.get('text') else 'executor_direct',assistance_reason=reason)
if action=='execute':
    self._change(job_id,{'prompt_ready'},'execution_dispatching',action)
    task=None
    try:
        task=self.runtime.submit(job['prepared_prompt'],str(uuid.uuid5(uuid.NAMESPACE_URL,'iald-coordination:'+job_id)),routing_prompt=job['prompt'],start_worker=False,execution_constraints=job['execution_constraints'])
        value=self._change(job_id,{'execution_dispatching'},'execution_waiting','execution_bound',execution_task_id=task['id'])
    except Exception:
        if task:self.runtime.cancel(task['id'])
        current=self.get(job_id)
        if current['stage']=='execution_dispatching':
            self._change(job_id,{'execution_dispatching'},'failed','execution_failed',error='Não foi possível registrar a execução; nenhuma nova chamada foi iniciada.')
        raise
    self.runtime.start_worker()
    return value
if action=='sync_execution':
    if job['stage']!='execution_waiting':return job
    task=job['execution']
    if task['status']=='result_ready':
        return self._change(job_id,{'execution_waiting'},'synthesis_ready',action)
    if task['status'] in ('failed','cancelled','interrupted'):
        return self._change(job_id,{'execution_waiting'},'failed',action,error=task['error'] or task['status'])

def submit(self, prompt, request_id, *, routing_prompt=None, start_worker=True, execution_constraints=None):
    constraints=controls.normalize(execution_constraints)
    prompt = validate_prompt(prompt,controls.prompt_limit(constraints))
    constraints_json=controls.encode(constraints)
    routing_prompt = validate_prompt(routing_prompt,controls.prompt_limit(constraints)) if routing_prompt is not None else prompt
    if not isinstance(request_id, str):
        raise ValueError("Identificador de tarefa inválido.")
    uuid.UUID(request_id)
    if not self.source_status()["ok"]:
        raise ValueError("Fontes do Supercondutor indisponíveis ou alteradas.")
    with self.db() as db:
        existing=db.execute('SELECT * FROM tasks WHERE request_id=?',(request_id,)).fetchone()
    if existing:
        if existing['prompt'] != prompt or (existing['routing_prompt'] or existing['prompt']) != routing_prompt or (existing['execution_constraints'] or 'null') != constraints_json:
            raise ValueError('Identificador já usado com outro pedido/restrições.')
        return self.task(existing['id'])
    retired=BASE/'state/session_requests'/f'{request_id}.json'
    if retired.is_file() and json.loads(retired.read_bytes()).get('status')=='superseded_before_submission':
        raise ValueError('Pedido retirado antes da submissão; execução proibida.')
    if constraints:
        preview=self.preview(prompt,constraints)
        if not preview['selected']:
            raise ValueError('Executor obrigatório indisponível ou inelegível; sem substituição.')
    stamp, task_id = now(), str(uuid.uuid4())
    with self.db() as db:
        db.execute("BEGIN IMMEDIATE")
        existing = db.execute("SELECT id,prompt,routing_prompt,execution_constraints FROM tasks WHERE request_id=?", (request_id,)).fetchone()
        if existing:
            if existing["prompt"] != prompt or (existing["routing_prompt"] or existing["prompt"]) != routing_prompt or (existing["execution_constraints"] or "null") != constraints_json:
                raise ValueError("Identificador já usado por outra tarefa.")
            return self.task(existing["id"])
        pending = db.execute("SELECT count(*) FROM tasks WHERE status IN ('queued','running')").fetchone()[0]
        if pending >= 5:
            raise ValueError("Fila cheia: aguarde uma das tarefas em andamento.")
        db.execute("INSERT INTO tasks(id,request_id,prompt,created_at,updated_at,status,routing_prompt,execution_constraints) VALUES(?,?,?,?,?,'queued',?,?)",
                   (task_id, request_id, prompt, stamp, stamp, routing_prompt, constraints_json))
    if start_worker:self.start_worker()

def _drain(self):
    # Keep the legacy process lock for the WHOLE drain: old workers and
    # recovery cannot overlap this owner. Only this owner fans out calls.
    from concurrent.futures import ThreadPoolExecutor, wait, FIRST_COMPLETED
    parallel = {'kimi', 'mimo', 'deepseek'}
    with self.worker_lock, process_lock(self.db_path):
        with ThreadPoolExecutor(max_workers=3) as pool:
            active = {}
            while True:
                for future in list(active):
                    if future.done():
                        # Unexpected worker failure remains running/uncertain;
                        # never reclaim or retry it automatically.
                        future.result()
                        del active[future]
                occupied = set(active.values())
                claimed = None
                with self.db() as db:
                    db.execute("BEGIN IMMEDIATE")
                    # Any persisted running task not owned by our futures is
                    # uncertain. At entry no calls may be recovered by retry.
                    running_count = db.execute("SELECT count(*) FROM tasks WHERE status='running'").fetchone()[0]
                    if running_count > len(active):
                        break

def test_every_executor_receives_same_packet_without_network(self):
    packet = memory.prepare('Cartan', self.index)
    receipt = packet['receipt']
    received = {}
    with ExitStack() as stack:
        stack.enter_context(patch('iald_orchestrator.canonical_memory.prepare', return_value=packet))
        stack.enter_context(patch('iald_orchestrator.providers.client_command', return_value=['mock-client']))
        for name in ('antigravity','kimi','mimo'):
            stack.enter_context(patch(f'iald_orchestrator.{name}.connection_status', return_value='ready'))
            def execute(prompt, _name=name, **kwargs):
                received[_name] = prompt
                return {'text':'ok','usage':{}}
            stack.enter_context(patch(f'iald_orchestrator.{name}.execute', side_effect=execute))
        def local(request, **kwargs):
            received['local'] = json.loads(request.data)['messages'][1]['content']
            response = MagicMock()
            response.__enter__.return_value.read.return_value = json.dumps({'choices':[{'finish_reason':'stop','message':{'content':'ok'}}]}).encode()
            return response
        stack.enter_context(patch('iald_orchestrator.providers.urllib.request.urlopen', side_effect=local))
        def process(args, **kwargs):
            name = 'codex' if 'exec' in args else 'claude'
            proc = MagicMock(returncode=0)
            def communicate(prompt, **kw):
                received[name] = prompt
                if name == 'codex':
                    return '\n'.join(json.dumps(x) for x in [{'type':'item.completed','item':{'type':'agent_message','text':'ok'}},{'type':'turn.completed','usage':{}}]), ''
                return json.dumps({'subtype':'success','result':'ok','usage':{}}), ''
            proc.communicate.side_effect = communicate
            return proc
        stack.enter_context(patch('iald_orchestrator.providers.subprocess.Popen', side_effect=process))
        for name in ('local','codex','claude','gemini','kimi','mimo'):
            result = providers.execute(name, 'Cartan', self.root)
            self.assertEqual(result['canonical_memory'], receipt)
    self.assertEqual(len(received), 6)
    for text in received.values():
        self.assertIn(packet['prompt'], text)

